action.code:
if (open_list.empty()) {
    return nullptr;
}

size_t best_index = 0;
Node* best_node = open_list[0];

for (size_t i = 1; i < open_list.size(); ++i) {
    if (open_list[i]->f < best_node->f) {
        best_node = open_list[i];
        best_index = i;
    }
}

open_list.erase(open_list.begin() + best_index);
return best_node;
// END_CODE

